surfaces.childText:
{[1, 2, 3, 4, 5].map((n) => (
        <button
          key={n}
          type="button"
          role="radio"
          aria-checked={value === n}
          aria-label={String(n)}
          ref={(button) => {
            buttons.current[n - 1] = button
          }}
          tabIndex={n === (value || 1) ? 0 : -1}
          onClick={() => onChange(n)}
          onKeyDown={(event) => {
            const direction =
              event.key === 'ArrowRight' || event.key === 'ArrowDown'
                ? 1
                : event.key === 'ArrowLeft' || event.key === 'ArrowUp'
                  ? -1
                  : 0
            if (!direction) return
            event.preventDefault()
            const next = ((n - 1 + direction + 5) % 5) + 1
            onChange(next)
